      "importancia": "media",
      "evidencia": "Hora fin 12:14, dentro del turno (07:30‑13:30)."
    }
  ],
  "desviacion_del_ranking": "ninguna",
  "trade_offs": [
    "Mayor costo respecto a la estrategia B (S/ 356.1 vs S/ 289.2).",
    "Uso de todos los vehículos de la flota, sin reducción de unidades."
